    @BeforeEach void isolateRemaining(){assertTrue(Boolean.TRUE.equals(jdbc.execute((org.springframework.jdbc.core.ConnectionCallback<Boolean>)connection->connection.getMetaData().getURL().startsWith("jdbc:h2:mem:apicc-collaboration-t6-remaining"))));for(String table:List.of("collaboration_storage_references","collaboration_storage_objects","collaboration_storage_accounts","collaboration_management_audit","collaboration_member_uploads","collaboration_previews","collaboration_publications","collaboration_publication_versions","collaboration_policy"))jdbc.update("DELETE FROM "+table);deployment.setDefaults(null);}
