    void reviewManager(Fixture f,Actor actor,boolean mock)throws Exception{
        String path=f.url()+"/access-members/"+actor.id();
        long revision=body(mvc.perform(get(path).header("Authorization","Bearer "+f.owner().token())).andExpect(status().isOk())).path("revision").asLong();
        request(f.owner().token(),put(path),Map.of("expectedRevision",revision,"role","ADMIN","capabilities",Map.of("mock.manage",mock?"allow":"deny","publication.manage",mock?"deny":"allow","history.read","deny"))).andExpect(status().isOk());
    }
    @ParameterizedTest @ValueSource(strings={"cancel","receipt","operation"}) void reviewMockManagementNoBodyRoutes(String route)throws Exception{
        var f=fixture();
        mockEnabled(f,Map.of("sharedMockAllowed",true));
        reviewManager(f,f.editor(),true);
        reviewManager(f,f.viewer(),false);
        preview(f,f.viewer(),documentRequest(f)); // Actual ordinary-purpose positive, no Mock authority.
        var ownerControl=preview(f,f.owner(),mock(f));
        mvc.perform(delete(collaboration(f)+"/previews/"+ownerControl.path("id").asText()).header("Authorization","Bearer "+f.owner().token())).andExpect(status().isNoContent());
        var candidate=preview(f,f.owner(),mock(f));
        String id=candidate.path("id").asText();
        mvc.perform(get(collaboration(f)+"/previews/"+id).header("Authorization","Bearer "+f.editor().token())).andExpect(status().isOk());
        if(route.equals("operation")){
            String intent=UUID.randomUUID().toString();
            var published=body(request(f.owner().token(),post(collaboration(f)+"/publications"),confirmation(candidate,intent)).andExpect(status().isCreated()));
            mvc.perform(get(collaboration(f)+"/operations/"+intent).header("Authorization","Bearer "+f.owner().token())).andExpect(status().isOk());
            var manager=mvc.perform(get(collaboration(f)+"/operations/"+intent).header("Authorization","Bearer "+f.editor().token())).andReturn().getResponse();
            var reverse=mvc.perform(get(collaboration(f)+"/operations/"+intent).header("Authorization","Bearer "+f.viewer().token())).andReturn().getResponse();
            assertAll(()->assertEquals(200,manager.getStatus()),()->assertEquals(published.path("id"),json.readTree(manager.getContentAsByteArray()).path("publicationId")),()->response(reverse,403,"forbidden"));
        }else if(route.equals("receipt")){
            artifactTime.advance(600000);
            storage.cleanup(Long.parseLong(f.workspace()),Long.parseLong(f.project()));
            assertNull(jdbc.queryForObject("SELECT body FROM collaboration_previews WHERE id=?",byte[].class,Long.parseLong(id)),"official cleanup really removed the body");
            assertNull(jdbc.queryForObject("SELECT source_json FROM collaboration_previews WHERE id=?",String.class,Long.parseLong(id)),"receipt cannot recover kind from a body/source bag");
            var manager=mvc.perform(get(collaboration(f)+"/previews/"+id).header("Authorization","Bearer "+f.editor().token())).andReturn().getResponse();
            var reverse=mvc.perform(get(collaboration(f)+"/previews/"+id).header("Authorization","Bearer "+f.viewer().token())).andReturn().getResponse();
            assertAll(()->response(manager,410,"preview_expired"),()->response(reverse,403,"forbidden"));
        }else{
            var reverse=mvc.perform(delete(collaboration(f)+"/previews/"+id).header("Authorization","Bearer "+f.viewer().token())).andReturn().getResponse();
            var manager=mvc.perform(delete(collaboration(f)+"/previews/"+id).header("Authorization","Bearer "+f.editor().token())).andReturn().getResponse();
            assertAll(()->response(reverse,403,"forbidden"),()->assertEquals(204,manager.getStatus()),()->assertEquals("cancelled",jdbc.queryForObject("SELECT state FROM collaboration_previews WHERE id=?",String.class,Long.parseLong(id))));
        }
    }
    @ParameterizedTest @org.junit.jupiter.params.provider.CsvSource({"history,empty","history,null","history,missing","publications,empty","publications,null","publications,missing"}) void reviewCursorRootAndRequiredFields(String list,String shape)throws Exception{
        var f=fixture();
        for(int n=0;n<3;n++)upload(f,f.editor());
        String path=collaboration(f)+"/"+list;
        var first=body(mvc.perform(get(path).param("limit","1").header("Authorization","Bearer "+f.owner().token())).andExpect(status().isOk()));
        String valid=first.path("nextCursor").asText();
        assertFalse(valid.isEmpty(),"actual first page has another real row");
        mvc.perform(get(path).param("limit","1").param("cursor",valid).header("Authorization","Bearer "+f.owner().token())).andExpect(status().isOk());
        JsonNode invalid=shape.equals("null")?json.nullNode():json.createObjectNode();
        if(shape.equals("missing")){
            invalid=json.readTree(Base64.getUrlDecoder().decode(valid));
            ((ObjectNode)invalid).remove("lastId");
        }
        String cursor=Base64.getUrlEncoder().withoutPadding().encodeToString(json.writeValueAsBytes(invalid));
        var result=mvc.perform(get(path).param("limit","1").param("cursor",cursor).header("Authorization","Bearer "+f.owner().token())).andReturn().getResponse();
        response(result,400,"collaboration_cursor_invalid");
    }
