    @ParameterizedTest @ValueSource(strings={"normal","audit-fault"}) void remainingWorkspaceDeletion(String outcome)throws Exception{
        var f=fixture();var other=fixture();var member=upload(f,f.editor());var document=saved(f);var otherDocument=saved(other);var workspacePolicy="/api/v1/workspaces/"+f.workspace()+"/collaboration/policy";long revision=body(mvc.perform(get(workspacePolicy).header("Authorization","Bearer "+f.owner().token())).andExpect(status().isOk())).path("revision").asLong();request(f.owner().token(),put(workspacePolicy),Map.of("expectedRevision",revision,"settings",Map.of("maxFieldBytes",4096))).andExpect(status().isOk());policy(f,false,Map.of("maxFieldBytes",2048));var accepted=json.createObjectNode().put("title","Same accepted source").put("includeEvidence",false);accepted.putObject("source").put("kind","member-history").put("uploadId",member.at("/source/uploadId").asText());var pending=preview(f,f.owner(),accepted);mvc.perform(get(collaboration(f)+"/previews/"+pending.path("id").asText()).header("Authorization","Bearer "+f.owner().token())).andExpect(status().isOk());publication(f,f.viewer(),document.path("id").asText());item(f,"member-history",member.at("/source/uploadId").asText());assertTrue(jdbc.queryForObject("SELECT COUNT(*) FROM collaboration_storage_references WHERE workspace_id=?",Long.class,Long.parseLong(f.workspace()))>0);var before=workspaceSnapshot(f);var otherBefore=workspaceSnapshot(other);var global=storage.usage(0,0);var auditIds=jdbc.queryForList("SELECT id FROM collaboration_management_audit WHERE workspace_id=?",Long.class,Long.parseLong(f.workspace()));
        if(outcome.equals("audit-fault")){ArtifactRetentionTest.AuditFault.attempts.set(0);jdbc.execute("CREATE TRIGGER t6_remaining_workspace_audit_fault BEFORE INSERT ON collaboration_management_audit FOR EACH ROW CALL '"+ArtifactRetentionTest.AuditFault.class.getName()+"'");try{try{mvc.perform(delete("/api/v1/workspaces/"+f.workspace()).header("Authorization","Bearer "+f.owner().token()));}catch(RuntimeException observed){}assertAll(()->assertTrue(ArtifactRetentionTest.AuditFault.attempts.get()>0,"actual workspace deletion audit INSERT reached"),()->assertEquals(before,workspaceSnapshot(f)),()->assertEquals(global,storage.usage(0,0)),()->assertEquals(otherBefore,workspaceSnapshot(other)));}finally{jdbc.execute("DROP TRIGGER t6_remaining_workspace_audit_fault");}return;}
        mvc.perform(delete("/api/v1/workspaces/"+f.workspace()).header("Authorization","Bearer "+f.owner().token())).andExpect(status().isNoContent());long ws=Long.parseLong(f.workspace());for(String table:List.of("collaboration_previews","collaboration_publications","collaboration_member_uploads","collaboration_storage_references","collaboration_publication_versions","collaboration_policy"))assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE workspace_id=?",Long.class,ws),"released actual "+table);assertAll(()->assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM collaboration_storage_objects WHERE workspace_id=? AND kind<>'AUDIT'",Long.class,ws)),()->assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM workspaces WHERE id=?",Long.class,ws)),()->assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM projects WHERE workspace_id=?",Long.class,ws)),()->assertTrue(jdbc.queryForObject("SELECT COUNT(*) FROM collaboration_management_audit WHERE workspace_id=?",Long.class,ws)>auditIds.size()),()->assertEquals(auditIds.size(),jdbc.queryForObject("SELECT COUNT(*) FROM collaboration_management_audit WHERE workspace_id=? AND id IN ("+String.join(",",Collections.nCopies(auditIds.size(),"?"))+")",Long.class,java.util.stream.Stream.concat(java.util.stream.Stream.of((Object)ws),auditIds.stream()).toArray()).intValue()),()->assertEquals(otherBefore,workspaceSnapshot(other)),()->assertEquals(0,jdbc.queryForObject("SELECT COALESCE(SUM(reserved_bytes),0) FROM collaboration_storage_accounts WHERE workspace_id=?",Long.class,ws)));boolean workspaceEvent=false;for(String raw:jdbc.queryForList("SELECT event_json FROM collaboration_management_audit WHERE workspace_id=?",String.class,ws)){var event=json.readTree(raw);if(event.path("action").asText().equals("WORKSPACE_DELETED")){workspaceEvent=true;assertEquals("WORKSPACE",event.path("objectKind").asText());assertEquals(ws,event.path("objectId").asLong());}}assertTrue(workspaceEvent,"finite workspace deletion event, not project0 deletion");publication(other,other.viewer(),otherDocument.path("id").asText());
    }

