    static class ObservedRequest extends MockHttpServletRequest {
        final byte[] bytes;final AtomicInteger consumed=new AtomicInteger();final ByteArrayInputStream input;
        ObservedRequest(ServletContext context,String path,String token,byte[] bytes){super(context,"POST",path);this.bytes=bytes;input=new ByteArrayInputStream(bytes);setContentType("application/json");addHeader("Authorization","Bearer "+token);}
        @Override public int getContentLength(){return -1;}@Override public long getContentLengthLong(){return -1;}
        @Override public ServletInputStream getInputStream(){return new ServletInputStream(){@Override public boolean isFinished(){return input.available()==0;}@Override public boolean isReady(){return true;}@Override public void setReadListener(ReadListener listener){}@Override public int read(){int value=input.read();if(value>=0)consumed.incrementAndGet();return value;}@Override public int read(byte[] value,int offset,int length){int count=input.read(value,offset,length);if(count>0)consumed.addAndGet(count);return count;}};}
    }
