        if(target.equals("history")||target.equals("purpose")){capability(f,f.owner(),target.equals("history")?"history.read":"publication.manage","deny");request(f.owner().token(),post(collaboration(f)+"/previews"),target.equals("history")?reportRequest(f):documentRequest(f)).andExpect(status().isForbidden());}
